#[test]
fn process_block_effects_teleporter_warps_player() {
    let mut rt = NativeRuntime::new(manifest());
    rt.block_list = Some(terrain::BlockList {
        prize_blocks: vec![],
        ghost_blocks: vec![],
        teleporters: vec![terrain::TeleporterEntry {
            layout_addr: 0x0000,
            col: 5,
            row: 3,
            dest_map_id: 0,
            dest_y: 10,
            dest_x: 20,
        }],
        hidden_blocks: vec![],
    });
    let mut slice = OpeningSliceState::new(default_bounds());
    slice.player.x_pos = 100 << 16;
    slice.player.y_pos = 200 << 16;
    slice.player.y_velocity = -0x2_0000;
    slice.player.on_ground = false;
    slice.teleporter_contact = Some((5, 3));

    rt.process_block_effects(&mut slice);

    assert_eq!(
        slice.player.x_pos,
        (20 * 16) << 16,
        "x should warp to dest col×16"
    );
    assert_eq!(
        slice.player.y_pos,
        (10 * 16) << 16,
        "y should warp to dest row×16"
    );
    assert_eq!(slice.player.y_velocity, 0, "velocity zeroed after warp");
    assert!(slice.player.on_ground, "player grounded after warp");
}

#[test]
fn process_block_effects_teleporter_no_op_without_block_list() {
    // If block_list is None, teleporter contact should be a no-op.
    let mut rt = NativeRuntime::new(manifest());
    let mut slice = OpeningSliceState::new(default_bounds());
    slice.player.x_pos = 100 << 16;
    slice.player.y_pos = 200 << 16;
    slice.teleporter_contact = Some((5, 3));

    rt.process_block_effects(&mut slice);

    assert_eq!(
        slice.player.x_pos,
        100 << 16,
        "player should not move without block_list"
    );
}

#[test]
fn align_player_for_down_hold_sub_7a10_shifts_right_when_left_probe_is_blocked() {
    let grid = grid_with_cells(8, 8, &[(1, 4, 0x60, 0)]);

    let alignment = align_player_for_down_hold_sub_7A10(&grid, 32 << 16, 64 << 16, 128);

    assert_eq!(
        alignment,
        DownHoldAlignmentSub7A10 {
            x_pos: 46 << 16,
            blocked: false,
        },
        "ASM sub_7A10 should snap Kid right to the next safe 14px clearance when the left probe cell is occupied",
    );
}

#[test]
fn align_player_for_down_hold_sub_7a10_shifts_left_when_right_probe_is_blocked() {
    let grid = grid_with_cells(8, 8, &[(2, 4, 0x60, 0)]);

    let alignment = align_player_for_down_hold_sub_7A10(&grid, 32 << 16, 64 << 16, 128);

    assert_eq!(
        alignment,
        DownHoldAlignmentSub7A10 {
            x_pos: 17 << 16,
            blocked: false,
        },
        "ASM sub_7A10 should snap Kid left by the low nibble plus one when the right probe cell is occupied",
    );
}

#[test]
fn align_player_for_down_hold_sub_7a10_restores_integer_x_when_both_sides_are_blocked() {
    let grid = grid_with_cells(8, 8, &[(1, 4, 0x60, 0), (3, 4, 0x60, 0)]);

    let alignment = align_player_for_down_hold_sub_7A10(&grid, (32 << 16) | 0x8000, 64 << 16, 128);

    assert_eq!(
        alignment,
        DownHoldAlignmentSub7A10 {
            x_pos: 32 << 16,
            blocked: true,
        },
        "ASM sub_7A10 should restore the original integer X when neither side can provide the required 14px clearance",
    );
}

